	protected FXQuote read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created FXQuote" );

		FXQuote entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read FXQuote with primary key" );
		msg.append( fXQuoteId );
		
		FXQuoteFetchOneSummary fetchOneSummary = new FXQuoteFetchOneSummary( fXQuoteId );

		try {
			entity = FXQuoteService.getFXQuoteInstance().getFXQuote( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found FXQuote " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a FXQuote.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a FXQuote." );

		StringBuilder msg = new StringBuilder( "Failed to update a FXQuote : " );        
		FXQuote entity = read();
		UpdateFXQuoteCommand command = generateUpdateCommand();
		command.setFXQuoteId(entity.getFXQuoteId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created FXQuote." );

			// for use later on...
			fXQuoteId = entity.getFXQuoteId();

			FXQuoteService proxy = FXQuoteService.getFXQuoteInstance();  

			proxy.updateFXQuote( command ).get();

			LOGGER.info( "-- Successfully saved FXQuote - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + fXQuoteId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a FXQuote.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created FXQuote." );

		FXQuote entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read FXQuote with id " + fXQuoteId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read FXQuote with id " + fXQuoteId );

			throw e;
		}

		try{
			FXQuoteService.getFXQuoteInstance().delete( new DeleteFXQuoteCommand( entity.getFXQuoteId() ) ).get();
			LOGGER.info( "-- Successfully deleted FXQuote with id " + fXQuoteId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete FXQuote with id " + fXQuoteId );

			throw e;
		}
	}

