		StringBuilder msg = new StringBuilder( "-- Failed to get all FXQuote : " );        
		List<FXQuote> collection  = new ArrayList<>();

		try {
			// call the static get method on the FXQuoteService
			collection = FXQuoteService.getFXQuoteInstance().getAllFXQuote();
			assertNotNull( collection, "An Empty collection of FXQuote was incorrectly returned.");
			
			// Now print out the values
			FXQuote entity = null;            
			Iterator<FXQuote> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getFXQuoteId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
